const group = new THREE.Group();
const concreteMat = new THREE.MeshStandardMaterial({ color: 0xcccccc });
const glassMat = new THREE.MeshStandardMaterial({ color: 0x88ccff, transparent: true, opacity: 0.4 });
const t = 0.1; // thickness ratio
const bottom = new THREE.Mesh(new THREE.BoxGeometry(width, height * t, depth), concreteMat);
bottom.position.y = -height/2 + (height * t)/2;
group.add(bottom);
const north = new THREE.Mesh(new THREE.BoxGeometry(width, height * (1-t), depth * t), concreteMat);
north.position.y = height/2 - (height * (1-t))/2;
north.position.z = depth/2 - (depth * t)/2;
group.add(north);
const east = new THREE.Mesh(new THREE.BoxGeometry(width * t, height * (1-t), depth * (1-2*t)), concreteMat);
east.position.y = height/2 - (height * (1-t))/2;
east.position.x = width/2 - (width * t)/2;
group.add(east);
const west = new THREE.Mesh(new THREE.BoxGeometry(width * t, height * (1-t), depth * (1-2*t)), concreteMat);
west.position.y = height/2 - (height * (1-t))/2;
west.position.x = -width/2 + (width * t)/2;
group.add(west);
const south = new THREE.Mesh(new THREE.BoxGeometry(width, height * (1-t), depth * t * 0.5), glassMat);
south.position.y = height/2 - (height * (1-t))/2;
south.position.z = -depth/2 + (depth * t * 0.25);
group.add(south);
return group;

